const slug = (s) =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');

const toFood = (id, name, category, kcal, protein, carbs, fat, fiber, servings, curated, micro) => ({
  id,
  name,
  category,
  per100: { kcal, protein, carbs, fat, fiber },
  micro: microFromList(micro), // micronutrients per 100 g (see nutrients.js), or null if unknown
  servings: [
    ...servings.map(([label, g]) => ({ label, g })),
    ...(category === 'Drinks' ? [{ label: '100 ml', g: 100 }] : [{ label: '100 g', g: 100 }, { label: '1 oz', g: 28.35 }]),
  ],
  liquid: category === 'Drinks',
  curated,
  _q: searchText(name),
});

// Restaurant menu items (NYC DOHMH MenuStat, 2017-2018). Nutrition comes per serving; when the chain
// published a weight it's converted to per 100 g like everything else, otherwise the item logs per serving.
const toRestaurantFood = ([id, item, chain, kcal, protein, carbs, fat, fiber, label, grams, micro]) => {
  const f = grams ? 100 / grams : 1;
  const r = (v) => Math.round(v * f * 10) / 10;
  const m = microFromList(micro);
  return {
    id,
    name: `${chain}: ${item}`,
    category: 'Restaurants',
    chain,
    per100: { kcal: Math.round(kcal * f), protein: r(protein), carbs: r(carbs), fat: r(fat), fiber: r(fiber) },
    micro: m ? scaleMicro(m, f) : null,
    servings: grams ? [{ label, g: grams }, { label: '100 g', g: 100 }] : [{ label, g: 100 }],
    perServing: !grams,
    liquid: false,
    curated: false,
    _q: searchText(`${chain}: ${item}`),
    _chain: searchText(chain),
  };
};

export const FOODS = [
  ...RAW.map(([name, category, kcal, protein, carbs, fat, fiber, servings]) =>
    toFood(`db-${slug(name)}`, name, category, kcal, protein, carbs, fat, fiber, servings, true, CURATED_MICROS[`db-${slug(name)}`])
  ),
  ...USDA.map(([id, name, category, kcal, protein, carbs, fat, fiber, servings, micro]) =>
    toFood(id, name, category, kcal, protein, carbs, fat, fiber, servings, false, micro)
  ),
  ...RESTAURANTS.map(toRestaurantFood),
];

// Build a "food" record from a user-defined custom food (nutrition per serving).
export function customToFood(c) {
  return {
    id: c.id,
    name: c.name,
    category: 'My foods',
    custom: true,
    by: c.by, // who made it (user id), when it came from the group's server
    // Custom foods store nutrition per one serving; treat a serving as a 100-unit basis.
    per100: { kcal: c.kcal || 0, protein: c.protein || 0, carbs: c.carbs || 0, fat: c.fat || 0, fiber: c.fiber || 0 },
    // Custom foods may carry a few micronutrients per serving (e.g. read off a label).
    micro: c.micro && Object.keys(c.micro).length ? c.micro : null,
    servings: [{ label: c.servingLabel || '1 serving', g: 100 }],
  };
}

// A custom food you made: tagged with your user id, or untagged (made on this phone and
// not yet back from the server). Foods others in the group added carry their id.
export const isMine = (f, auth) => f.by == null || !!(auth && f.by === auth.user.id);

export function nutritionFor(food, grams) {
  const f = grams / 100;
  const r = (n) => Math.round(n * f * 10) / 10;
  const out = {
    kcal: Math.round(food.per100.kcal * f),
    protein: r(food.per100.protein),
    carbs: r(food.per100.carbs),
    fat: r(food.per100.fat),
    fiber: r(food.per100.fiber || 0),
  };
  if (food.micro) out.micro = scaleMicro(food.micro, f);
  return out;
}

const FOOD_BY_ID = new Map(FOODS.map((f) => [f.id, f]));

// Micronutrients for a logged entry: stored on the entry (logged with 2.0.21+), or worked
// out from its food and grams for older entries. null when unknown (quick add, unknown food).
export function entryMicro(entry, customFoods = []) {
  if (entry.micro) return entry.micro;
  if (!entry.foodId || !(entry.grams > 0)) return null;
  const food = FOOD_BY_ID.get(entry.foodId) || ((customFoods || []).find((c) => c.id === entry.foodId) && customToFood(customFoods.find((c) => c.id === entry.foodId)));
  return food && food.micro ? scaleMicro(food.micro, entry.grams / 100) : null;
}

export { MICRONUTRIENTS };

// Best matches first: your own and hand-picked foods, then names that start with
// the search, then whole-phrase matches, then shorter (plainer) names.
export function searchFoods(query, foods, limit = 200) {
  const q = searchText(query.trim());
  if (!q) return foods;
  const words = q.split(/\s+/);
  const hits = [];
  for (const f of foods) {
    const n = f._q || f.name.toLowerCase();
    let all = true;
    for (const w of words) {
      if (!n.includes(w) && !f.category.toLowerCase().includes(w)) {
        all = false;
        break;
      }
    }
    if (!all) continue;
    const match = n.startsWith(q) ? 0 : n.includes(q) ? 1 : 2;
    // Restaurant items come after general foods, unless the search names the chain ("taco bell burrito").
    const own = f.custom ? 0 : f.curated ? 1 : f._chain ? (q.includes(f._chain) || f._chain.startsWith(words[0]) ? 1 : 3) : 2;
    hits.push({ f, score: match * 10 + own, len: n.length });
  }
  hits.sort((a, b) => a.score - b.score || a.len - b.len || a.f.name.localeCompare(b.f.name));
  return hits.slice(0, limit).map((x) => x.f);
}

export const MEALS = [
  { key: 'breakfast', label: 'Breakfast', icon: '🌅' },
  { key: 'lunch', label: 'Lunch', icon: '🥗' },
  { key: 'dinner', label: 'Dinner', icon: '🍽️' },
  { key: 'snack', label: 'Snacks', icon: '🍎' },
];

// Guess which meal the user is logging based on time of day.
export function mealForTime(date = new Date()) {
  const h = new Date(date).getHours();
  if (h >= 4 && h < 11) return 'breakfast';
  if (h >= 11 && h < 15) return 'lunch';
  if (h >= 17 && h < 22) return 'dinner';
  return 'snack';
}
